import { Component, computed, DestroyRef, effect, inject, input, output, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { DatePipe } from '@angular/common';
import { ResolucionService } from '../../services/resolucion.service';
import { AuthService } from '../../../services/auth.service';
import { ToastService } from '../../services/toast.service';
import { ToastContainerComponent } from '../toast-container/toast-container.component';
import { Resolucion } from '../../models/resolucion.model';
import { RecomendacionComite } from '../../models/sesion.model';
import {
  FirmaEfirmaModalComponent,
  DocumentoAFirmar,
  ResultadoFirma,
} from '../firma-efirma-modal/firma-efirma-modal.component';
import { SignMetadata } from '../../utils/pdf-sign.util';

type Modo = 'pre-dictaminacion' | 'en-dictaminacion' | 'historial';

@Component({
  selector: 'app-resolucion-panel',
  templateUrl: './resolucion-panel.component.html',
  host: { class: 'd-block' },
  imports: [DatePipe, FirmaEfirmaModalComponent, ToastContainerComponent],
})
export class ResolucionPanelComponent {
  private readonly resolucionService = inject(ResolucionService);
  private readonly authService = inject(AuthService);
  private readonly toastService = inject(ToastService);
  private readonly destroyRef = inject(DestroyRef);

  constructor() {
    effect(() => {
      if (this.modo() === 'historial') {
        this.cargarResoluciones();
      }
    });
  }

  folio = input.required<string>();
  status = input.required<string>();
  solicitudId = input<number>();
  rfc = input<string>();
  createdAt = input<string>();
  recomendacion = input<RecomendacionComite | null | undefined>(undefined);

  statusCambiado = output<void>();

  readonly modo = computed<Modo>(() => {
    const s = this.status();
    if (['Enviada', 'Incompleta', 'Subsanada', 'No Presentada'].includes(s)) {
      return 'pre-dictaminacion';
    }
    if (s === 'En Dictaminación') {
      return 'en-dictaminacion';
    }
    return 'historial';
  });

  readonly puedeActuar = computed(() => {
    const role = this.authService.currentUser()?.role;
    return role === 'ejecutivo' || role === 'admin';
  });

  readonly sentido = signal<'Autorizada' | 'No Autorizada'>('Autorizada');
  readonly generando = signal(false);
  readonly errorMsg = signal<string | null>(null);
  readonly exitoMsg = signal<string | null>(null);

  readonly resoluciones = signal<Resolucion[]>([]);
  readonly cargandoResoluciones = signal(false);

  readonly mostrarModalFirma = signal(false);

  private unsignedPdfBytes: Uint8Array | null = null;
  private resolucionId: number | null = null;

  readonly documentosAFirmar = computed<DocumentoAFirmar[]>(() => {
    if (!this.unsignedPdfBytes) return [];
    return [{ nombre: `resolucion_${this.folio()}.pdf`, bytes: this.unsignedPdfBytes }];
  });

  readonly firmaMetadata = computed<SignMetadata | undefined>(() => {
    const rfc = this.rfc();
    const createdAt = this.createdAt();
    if (!rfc || !createdAt) return undefined;
    return {
      solicitudId: this.solicitudId() ?? null,
      resolucionId: this.resolucionId ?? null,
      rfc,
      createdAt,
    };
  });

  generarResolucion(): void {
    this.generando.set(true);
    this.errorMsg.set(null);
    this.exitoMsg.set(null);
    this.resolucionService.generar(this.folio(), this.sentido()).pipe(takeUntilDestroyed(this.destroyRef)).subscribe({
      next: (res) => {
        this.resolucionId = res.resolucion_id;
        this.unsignedPdfBytes = this.base64ToUint8Array(res.pdf_base64);
        this.generando.set(false);
        this.mostrarModalFirma.set(true);
      },
      error: (err) => {
        this.generando.set(false);
        this.errorMsg.set(err.error?.message || 'No se pudo generar la resolución. Intente de nuevo.');
      },
    });
  }

  descargarSinFirmar(): void {
    if (!this.unsignedPdfBytes) return;
    const blob = new Blob([this.unsignedPdfBytes.buffer as ArrayBuffer], { type: 'application/pdf' });
    this.descargarBlob(blob, `resolucion_${this.folio()}.pdf`);
  }

  onFirmaCerrado(): void {
    this.mostrarModalFirma.set(false);
    this.errorMsg.set(null);
  }

  onFirmaFirmado(resultados: ResultadoFirma[]): void {
    if (resultados.length === 0 || !this.resolucionId) return;

    const firmado = resultados[0];
    const metadata = this.firmaMetadata();
    const metadataStr = metadata ? JSON.stringify({
      solicitudId: metadata.solicitudId ?? null,
      resolucionId: this.resolucionId,
      rfc: metadata.rfc,
      createdAt: metadata.createdAt,
    }) : undefined;

    this.resolucionService.firmar(this.folio(), this.resolucionId, firmado.signedBytes, metadataStr).pipe(takeUntilDestroyed(this.destroyRef)).subscribe({
      next: () => {
        this.mostrarModalFirma.set(false);
        const msg = 'Resolución firmada correctamente.';
        this.exitoMsg.set(msg);
        this.toastService.success(msg);
        this.statusCambiado.emit();
      },
      error: (err) => {
        const errMsg = err.error?.message || 'No se pudo guardar la firma. Intente de nuevo.';
        this.errorMsg.set(errMsg);
        this.toastService.error(errMsg);
      },
    });
  }

  cargarResoluciones(): void {
    this.cargandoResoluciones.set(true);
    this.resolucionService.getResoluciones(this.folio()).pipe(takeUntilDestroyed(this.destroyRef)).subscribe({
      next: (data) => {
        this.resoluciones.set(data);
        this.cargandoResoluciones.set(false);
      },
      error: () => {
        this.cargandoResoluciones.set(false);
        this.errorMsg.set('No se pudieron cargar las resoluciones.');
      },
    });
  }

  descargarResolucion(id: number): void {
    this.resolucionService.descargarResolucion(this.folio(), id).pipe(takeUntilDestroyed(this.destroyRef)).subscribe({
      next: (blob) => {
        this.descargarBlob(blob, `resolucion_${this.folio()}_${id}.pdf`);
      },
    });
  }

  private descargarBlob(blob: Blob, filename: string): void {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  }

  private base64ToUint8Array(base64: string): Uint8Array {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
  }
}
